import {builtInExercises,equipmentTypes,exerciseGuide,filterExercises,guideSources,exerciseRecordingHint} from './exercise-library.js';
import {muscleFigure,exercisePose} from './exercise-art.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groupLabels={chest:'胸',shoulders:'肩膀',back:'背',arms:'手臂',legs:'腿与臀',core:'核心'};

export function muscleExplorer(catalog,{selected='all',view='front',counts=null,compact=false}={}){
  const selectedName=groupLabels[selected]??'全身';
  return `<section class="anatomy-explorer ${compact?'anatomy-compact':''}" aria-label="可视化肌群选择"><div class="anatomy-stage"><div class="anatomy-stage-top"><span>BODY MAP <span class="anatomy-live-dot"></span></span><div class="anatomy-view" role="group" aria-label="人体视角"><button data-action="body-view" data-view="front" aria-pressed="${view==='front'}" class="${view==='front'?'active':''}">正面</button><button data-action="body-view" data-view="back" aria-pressed="${view==='back'}" class="${view==='back'?'active':''}">背面</button></div></div><div class="anatomy-grid-lines" aria-hidden="true"></div><div class="anatomy-human">${muscleFigure({view,selected,interactive:true})}</div><div class="anatomy-coordinate" aria-hidden="true"><span>01 / ${view==='front'?'ANTERIOR':'POSTERIOR'}</span><span>LIFTLOG MOVEMENT</span></div></div><div class="anatomy-copy"><span class="library-kicker">MOVE WITH INTENTION</span><h2>${compact?'今天，练哪里？':'找到今天的<br>发力点。'}</h2><p>${compact?'点选身体区域，查看对应动作。':'从身体部位出发，认识动作，再开始记录。'}</p><div class="anatomy-selection"><span class="anatomy-live-dot"></span><span>${selected==='all'?'选择一个训练部位':`已选择 · ${selectedName}`}</span></div><div class="anatomy-group-buttons">${catalog.map(g=>`<button data-action="muscle-select" data-group="${g.id}" aria-pressed="${selected===g.id}" class="${selected===g.id?'active':''}"><strong>${g.name}</strong><small>${counts?`近 7 天 ${counts[g.id]??0} 组`:`${g.exercises.length} 个动作`}</small><span aria-hidden="true">↗</span></button>`).join('')}</div><p class="anatomy-note">身体区域示意 · 不代表训练激活程度或恢复状态</p></div></section>`;
}

export function libraryToolbar({query='',equipment='all',group='all'}={}){
  return `<section class="library-tools" aria-label="动作搜索与筛选"><label class="library-search"><span aria-hidden="true">⌕</span><input id="exercise-search" type="search" maxlength="80" value="${esc(query)}" placeholder="搜索动作、器械或肌肉" aria-label="搜索动作、器械或肌肉" autocomplete="off"></label><label class="library-equipment"><span>器械</span><select id="exercise-equipment" aria-label="筛选器械"><option value="all">全部器械</option>${equipmentTypes.map(t=>`<option value="${t}" ${equipment===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="secondary library-reset" data-action="reset-library">${query||equipment!=='all'||group!=='all'?'重置筛选':'全部动作'}</button></section><div id="exercise-results"></div>`;
}

export function exerciseCards(catalog,{query='',equipment='all',group='all'}={},data={sessions:[]}){
  const entries=filterExercises(catalog,{query,equipment,group},data.customExercises??[]);
  const cards=entries.map(e=>{
    const last=[...data.sessions].sort((a,b)=>b.date.localeCompare(a.date)).find(s=>s.exercises.some(x=>x.name===e.name));
    return `<article class="exercise-card visual-exercise-card"><button class="exercise-visual" data-action="exercise-guide" data-name="${esc(e.name)}" data-group="${e.group}" aria-label="查看 ${esc(e.name)} 动作姿势"><span class="exercise-equipment-chip">${esc(e.guide?.equipment??'自定义')}</span>${e.guide?exercisePose(e.guide,'end',{thumbnail:true}):`<div class="custom-anatomy">${muscleFigure({selected:e.group,view:e.group==='back'?'back':'front'})}</div>`}<span class="exercise-visual-hint">${e.guide?'动作示意':'部位示意'} <span aria-hidden="true">↗</span></span></button><div class="exercise-card-copy"><div class="exercise-card-group">${esc(e.groupName)}${e.guide?.tracking==='reps'||e.custom?.tracking==='reps'?' · 自重次数':''}</div><h3>${esc(e.name)}</h3><p class="exercise-primary">${esc(e.guide?.primary??e.custom?.note??'自定义动作 · 尚无姿势示意')}</p><small>${last?'最近记录 · '+esc(last.date):'还没有训练记录'}</small><div class="exercise-card-actions"><button class="text-btn" data-action="exercise-guide" data-name="${esc(e.name)}" data-group="${e.group}">查看动作</button><button class="primary" data-action="start-exercise" data-name="${esc(e.name)}" data-group="${e.group}" aria-label="加入 ${esc(e.name)} 到训练">＋ 加入</button></div>${e.custom?`<button class="danger delete-custom-button" data-action="delete-custom" data-id="${esc(e.custom.id)}" aria-label="删除自定义动作 ${esc(e.name)}">删除自定义动作</button>`:''}</div></article>`;
  }).join('');
  return `<div class="section-head library-result-heading"><h2>${groupLabels[group]?groupLabels[group]+'部动作':'全部动作'} <span class="library-result-number" role="status">${entries.length}</span></h2><button class="view-link" data-action="new-custom">＋ 自定义动作</button></div>${entries.length?`<div class="visual-library-grid">${cards}</div>`:'<div class="panel library-no-results"><h3>没有找到符合条件的动作</h3><p>试试其他关键词或器械，也可以添加自己的动作。</p><button class="secondary" data-action="reset-library">清除筛选</button></div>'}`;
}

export function exerciseGuideMarkup(name,group,customExercises=[],{canAdd=true,inSession=false,recordingHint}={}){
  const g=exerciseGuide(name,customExercises),custom=customExercises.find(e=>e.name===name);
  const groupName=groupLabels[group]??'训练';
  const measures=recordingHint??exerciseRecordingHint(name,customExercises);
  return `<header class="dialog-header guide-header"><div><p class="library-kicker">MOVEMENT GUIDE</p><h2 id="guide-title">${esc(name)}</h2></div><button class="icon-button" data-action="close-guide" aria-label="关闭动作详情">×</button></header><div class="dialog-body guide-body"><div class="guide-meta"><span class="chip">${esc(groupName)}</span><span class="chip">${esc(g?.equipment??'自定义动作')}</span><span class="guide-local">离线可查看</span></div>${g?`<div class="guide-step-controls" role="group" aria-label="动作示意阶段"><button data-action="guide-step" data-step="start" aria-pressed="false">起始姿势</button><button data-action="guide-step" data-step="end" aria-pressed="false">结束姿势</button><button data-action="guide-step" data-step="compare" aria-pressed="true" class="active">并排对照</button></div><div class="guide-frames" data-step="compare"><figure data-frame="start"><div class="guide-frame-label"><span>01</span>起始姿势</div>${exercisePose(g,'start')}<figcaption>${esc(g.steps[0])}</figcaption></figure><figure data-frame="end"><div class="guide-frame-label"><span>02</span>结束姿势</div>${exercisePose(g,'end')}<figcaption>${esc(g.steps[1])}</figcaption></figure></div><p class="guide-diagram-note">${esc(g.patternName)}模式示意 · 器械结构与个人活动范围会有差异。</p><div class="guide-detail-grid"><section class="guide-muscles"><div class="guide-mini-body">${muscleFigure({selected:group,view:group==='back'?'back':'front',secondary:g.secondary})}</div><div><h3>参与部位</h3><p class="guide-primary-label"><i></i>主要 · ${esc(g.primary)}</p><p class="guide-secondary-label"><i></i>协同 · ${esc(g.secondary.map(s=>groupLabels[s]).join('、')||'未额外标注')}</p><small>区域示意不表示各肌肉的参与比例。</small></div></section><section class="guide-cues"><h3>记住这两点</h3><ol>${g.cues.map(c=>`<li>${esc(c)}</li>`).join('')}</ol></section></div>`:`<section class="guide-custom-empty"><div class="guide-mini-body">${muscleFigure({selected:group,view:group==='back'?'back':'front'})}</div><h3>这是你的自定义动作</h3><p>${esc(custom?.note||'尚未提供这个动作的姿势示意。请依据实际器械说明确认使用方式。')}</p></section>`}<section class="guide-recording"><h3>怎样记进 LiftLog</h3><p>${esc(measures)}</p>${g?.variant==='single'||g?.pattern==='lunge'?'<p>单侧动作先按两侧分别完成并核对次数；同一条记录内请保持一致的计数口径。</p>':''}${g?.pattern==='deadbug'||g?.pattern==='birddog'||g?.pattern==='twist'?'<p>每完成一侧并回到中间计 1 次，两侧合计。</p>':''}</section>${g?`<details class="guide-references"><summary>资料与示意说明</summary><p>本图由 LiftLog 绘制，用于理解动作模式，不进行摄像头姿态识别或动作评分。实际器械使用请参考器械说明。</p>${guideSources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ↗</a>`).join('')}</details>`:''}</div><footer class="dialog-footer guide-footer"><button class="secondary" data-action="close-guide">${inSession?'返回训练':'返回动作库'}</button>${canAdd?`<button class="primary" data-action="guide-add" data-name="${esc(name)}" data-group="${esc(group)}">＋ 加入本次训练</button>`:''}</footer>`;
}
